head.b:skin:
/*
-----------------------------------------------
Theme Name   : Pesona Green Residence - Premium Blogger Theme
Version      : 1.0.0
Author       : Pesonaku
Design Style : Light Green, Modern, Luxury & High Conversion Real Estate Landing Page
-----------------------------------------------
<Variable name="primaryColor" description="Warna Utama (Emerald)" type="color" default="#10b981" value="#10b981"/>
<Variable name="primaryDark" description="Warna Utama Gelap" type="color" default="#059669" value="#059669"/>
<Variable name="primaryLight" description="Warna Latar Lembut" type="color" default="#ecfdf5" value="#ecfdf5"/>
<Variable name="accentGold" description="Warna Aksen Promo" type="color" default="#f59e0b" value="#f59e0b"/>
<Variable name="darkText" description="Warna Teks Utama" type="color" default="#0f172a" value="#0f172a"/>
<Variable name="mutedText" description="Warna Teks Sekunder" type="color" default="#64748b" value="#64748b"/>
<Variable name="cardBg" description="Warna Background Card" type="color" default="#ffffff" value="#ffffff"/>
*/

:root {
  --primary: $(primaryColor);
  --primary-dark: $(primaryDark);
  --primary-light: $(primaryLight);
  --accent-gold: $(accentGold);
  --text-dark: $(darkText);
  --text-muted: $(mutedText);
  --bg-card: $(cardBg);
  --bg-page: #f8fafc;
  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 20px;
  --radius-full: 9999px;
  --shadow-soft: 0 10px 25px -5px rgba(16, 185, 129, 0.08), 0 8px 10px -6px rgba(0, 0, 0, 0.04);
  --shadow-hover: 0 20px 30px -10px rgba(16, 185, 129, 0.18), 0 10px 15px -5px rgba(0, 0, 0, 0.05);
  --font-sans: 'Plus Jakarta Sans', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-page);
  color: var(--text-dark);
  line-height: 1.6;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
  transition: all 0.25s ease;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

.container {
  width: 100%;
  max-width: 1200px;
  margin-left: auto;
  margin-right: auto;
  padding-left: 20px;
  padding-right: 20px;
}

.section-pad {
  padding-top: 80px;
  padding-bottom: 80px;
}

.section-header {
  text-align: center;
  max-width: 680px;
  margin: 0 auto 50px auto;
}

.badge-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 16px;
  background: var(--primary-light);
  color: var(--primary-dark);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-radius: var(--radius-full);
  margin-bottom: 14px;
  border: 1px solid rgba(16, 185, 129, 0.2);
}

.section-title {
  font-size: 2.25rem;
  font-weight: 800;
  color: var(--text-dark);
  letter-spacing: -0.02em;
  line-height: 1.25;
  margin-bottom: 16px;
}

.section-subtitle {
  font-size: 1.05rem;
  color: var(--text-muted);
}

/* BUTTONS */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  font-weight: 700;
  font-size: 0.95rem;
  padding: 14px 28px;
  border-radius: var(--radius-full);
  border: none;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.btn-primary {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  color: #ffffff !important;
  box-shadow: 0 10px 20px rgba(16, 185, 129, 0.3);
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 15px 25px rgba(16, 185, 129, 0.4);
  filter: brightness(1.05);
}

.btn-outline {
  background: #ffffff;
  color: var(--primary-dark) !important;
  border: 2px solid var(--primary);
}

.btn-outline:hover {
  background: var(--primary-light);
  transform: translateY(-2px);
}

.btn-sm {
  padding: 8px 18px;
  font-size: 0.85rem;
}

/* NAVBAR */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(226, 232, 240, 0.8);
  transition: all 0.3s ease;
}

.nav-wrap {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 78px;
}

.nav-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--text-dark);
  letter-spacing: -0.02em;
}

.nav-brand-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: linear-gradient(135deg, var(--primary), var(--primary-dark));
  display: flex;
  align-items: center;
  justify-content: center;
  color: #ffffff;
  font-weight: 800;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
  list-style: none;
}

.nav-link {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-muted);
}

.nav-link:hover {
  color: var(--primary-dark);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 14px;
}

.nav-profile-pic {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  border: 2px solid var(--primary);
  object-fit: cover;
}

.hamburger-btn {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  font-size: 1.6rem;
  color: var(--text-dark);
}

/* HERO BANNER & SLIDER */
.hero-section {
  position: relative;
  padding-top: 130px;
  padding-bottom: 70px;
  background: radial-gradient(circle at 10% 20%, rgba(236, 253, 245, 0.8) 0%, rgba(248, 250, 252, 1) 70%);
  overflow: hidden;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1.05fr;
  gap: 50px;
  align-items: center;
}

.hero-headline {
  font-size: 3.1rem;
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.03em;
  color: var(--text-dark);
  margin-bottom: 20px;
}

.hero-headline span {
  color: var(--primary);
  position: relative;
}

.hero-desc {
  font-size: 1.15rem;
  color: var(--text-muted);
  margin-bottom: 32px;
  line-height: 1.7;
}

.hero-btns {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 36px;
}

.hero-slider-wrap {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: 0 25px 50px -12px rgba(16, 185, 129, 0.25);
  background: #000;
}

.hero-slides {
  position: relative;
  width: 100%;
  height: 440px;
}

.hero-slide {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.8s ease, visibility 0.8s ease;
}

.hero-slide.active {
  opacity: 1;
  visibility: visible;
}

.hero-slide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero-slide-badge {
  position: absolute;
  bottom: 24px;
  left: 24px;
  right: 24px;
  background: rgba(15, 23, 42, 0.75);
  backdrop-filter: blur(8px);
  color: #fff;
  padding: 14px 20px;
  border-radius: var(--radius-md);
  border: 1px solid rgba(255, 255, 255, 0.15);
}

.hero-slide-badge h4 {
  font-size: 1.1rem;
  font-weight: 700;
  color: #fff;
}

.hero-slide-badge p {
  font-size: 0.85rem;
  color: #cbd5e1;
}

.slider-nav {
  position: absolute;
  bottom: 24px;
  right: 30px;
  display: flex;
  gap: 8px;
  z-index: 10;
}

.slider-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.4);
  cursor: pointer;
  transition: all 0.3s ease;
}

.slider-dot.active {
  width: 28px;
  border-radius: 6px;
  background: var(--primary);
}

/* KEUNGGULAN (USP) */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 24px;
}

.feature-card {
  background: var(--bg-card);
  border-radius: var(--radius-md);
  padding: 28px 24px;
  border: 1px solid #e2e8f0;
  box-shadow: var(--shadow-soft);
  transition: all 0.3s ease;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.feature-card:hover {
  transform: translateY(-5px);
  border-color: var(--primary);
  box-shadow: var(--shadow-hover);
}

.feature-icon-box {
  width: 52px;
  height: 52px;
  border-radius: 12px;
  background: var(--primary-light);
  color: var(--primary-dark);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}

.feature-card h3 {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-dark);
}

.feature-card p {
  font-size: 0.9rem;
  color: var(--text-muted);
}

/* LISTING TIPE RUMAH */
.listing-filter-wrap {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-bottom: 40px;
}

.filter-btn {
  padding: 10px 24px;
  font-size: 0.9rem;
  font-weight: 700;
  border-radius: var(--radius-full);
  border: 1px solid #e2e8f0;
  background: #fff;
  color: var(--text-muted);
  cursor: pointer;
  transition: all 0.25s ease;
}

.filter-btn.active, .filter-btn:hover {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
  box-shadow: 0 4px 12px rgba(16, 185, 129, 0.25);
}

.listing-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 30px;
}

.property-card {
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid #e2e8f0;
  box-shadow: var(--shadow-soft);
  transition: all 0.3s ease;
  display: flex;
  flex-direction: column;
}

.property-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-hover);
  border-color: rgba(16, 185, 129, 0.4);
}

.property-thumb-wrap {
  position: relative;
  height: 230px;
  overflow: hidden;
}

.property-thumb-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s ease;
}

.property-card:hover .property-thumb-wrap img {
  transform: scale(1.05);
}

.property-badge {
  position: absolute;
  top: 16px;
  left: 16px;
  padding: 5px 14px;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.badge-subsidi {
  background: #10b981;
  color: #fff;
}

.badge-komersil {
  background: #0284c7;
  color: #fff;
}

.property-body {
  padding: 24px;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.property-title {
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--text-dark);
  margin-bottom: 6px;
}

.property-price {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--primary-dark);
  margin-bottom: 4px;
}

.property-installment {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-bottom: 18px;
}

.property-specs-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  padding: 14px 0;
  border-top: 1px dashed #e2e8f0;
  border-bottom: 1px dashed #e2e8f0;
  margin-bottom: 20px;
  text-align: center;
}

.spec-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.spec-icon {
  font-size: 1.1rem;
  color: var(--primary-dark);
}

.spec-label {
  font-size: 0.75rem;
  color: var(--text-muted);
  font-weight: 600;
}

.property-actions {
  display: flex;
  gap: 10px;
  margin-top: auto;
}

/* MODAL DETAIL POPUP */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(15, 23, 42, 0.75);
  backdrop-filter: blur(5px);
  z-index: 2000;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.modal-overlay.active {
  display: flex;
}

.modal-box {
  background: #fff;
  border-radius: var(--radius-lg);
  max-width: 800px;
  width: 100%;
  max-height: 90vh;
  overflow-y: auto;
  position: relative;
  padding: 32px;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.25);
}

.modal-close-btn {
  position: absolute;
  top: 20px;
  right: 20px;
  background: #f1f5f9;
  border: none;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  cursor: pointer;
  font-size: 1.2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-dark);
}

.modal-gallery-main {
  width: 100%;
  height: 320px;
  border-radius: var(--radius-md);
  overflow: hidden;
  margin-bottom: 12px;
}

.modal-gallery-main img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.modal-thumbs {
  display: flex;
  gap: 10px;
  margin-bottom: 24px;
  overflow-x: auto;
}

.modal-thumb {
  width: 80px;
  height: 60px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  border: 2px solid transparent;
  object-fit: cover;
}

.modal-thumb.active {
  border-color: var(--primary);
}

/* GALERI AKTIVITAS */
.gallery-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 16px;
}

.gallery-item {
  position: relative;
  height: 220px;
  border-radius: var(--radius-md);
  overflow: hidden;
  cursor: pointer;
}

.gallery-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.gallery-item:hover img {
  transform: scale(1.08);
}

.gallery-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(15, 23, 42, 0.8) 0%, transparent 60%);
  display: flex;
  align-items: flex-end;
  padding: 16px;
  color: #fff;
  opacity: 0;
  transition: opacity 0.3s ease;
}

.gallery-item:hover .gallery-overlay {
  opacity: 1;
}

/* MARKETING PROFILE */
.marketing-card {
  background: linear-gradient(135deg, #ffffff 0%, var(--primary-light) 100%);
  border-radius: var(--radius-lg);
  padding: 40px;
  border: 1px solid rgba(16, 185, 129, 0.2);
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 40px;
  align-items: center;
  box-shadow: var(--shadow-soft);
}

.marketing-photo {
  width: 190px;
  height: 190px;
  border-radius: var(--radius-lg);
  object-fit: cover;
  border: 4px solid #fff;
  box-shadow: 0 10px 20px rgba(0, 0, 0, 0.08);
}

.marketing-info h3 {
  font-size: 1.8rem;
  font-weight: 800;
  color: var(--text-dark);
  margin-bottom: 6px;
}

.marketing-role {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--primary-dark);
  margin-bottom: 14px;
}

.marketing-bio {
  font-size: 1rem;
  color: var(--text-muted);
  margin-bottom: 24px;
  line-height: 1.7;
}

/* FAQ ACCORDION */
.faq-wrap {
  max-width: 820px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.faq-item {
  background: var(--bg-card);
  border: 1px solid #e2e8f0;
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: border-color 0.25s ease;
}

.faq-item.active {
  border-color: var(--primary);
}

.faq-question {
  padding: 20px 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
  font-weight: 700;
  font-size: 1.05rem;
  color: var(--text-dark);
  user-select: none;
}

.faq-icon {
  font-size: 1.25rem;
  transition: transform 0.3s ease;
}

.faq-item.active .faq-icon {
  transform: rotate(180deg);
}

.faq-answer {
  padding: 0 24px;
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
  color: var(--text-muted);
  font-size: 0.95rem;
  line-height: 1.7;
}

.faq-item.active .faq-answer {
  padding: 0 24px 22px 24px;
  max-height: 250px;
}

/* TESTIMONI */
.testi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 24px;
}

.testi-card {
  background: var(--bg-card);
  border-radius: var(--radius-md);
  padding: 28px;
  border: 1px solid #e2e8f0;
  box-shadow: var(--shadow-soft);
}

.testi-stars {
  color: #f59e0b;
  font-size: 1.1rem;
  margin-bottom: 14px;
}

.testi-text {
  font-size: 0.95rem;
  color: var(--text-dark);
  line-height: 1.7;
  margin-bottom: 20px;
  font-style: italic;
}

.testi-user {
  display: flex;
  align-items: center;
  gap: 14px;
}

.testi-avatar {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  object-fit: cover;
}

.testi-name {
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--text-dark);
}

.testi-unit {
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* LOKASI & PETA */
.location-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 36px;
  align-items: center;
}

.location-card {
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  padding: 36px;
  border: 1px solid #e2e8f0;
  box-shadow: var(--shadow-soft);
}

.map-frame-wrap {
  height: 380px;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-soft);
  border: 1px solid #e2e8f0;
}

.map-frame-wrap iframe {
  width: 100%;
  height: 100%;
  border: none;
}

/* ARTIKEL & BLOG */
.articles-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 30px;
}

.article-card {
  background: var(--bg-card);
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid #e2e8f0;
  box-shadow: var(--shadow-soft);
  transition: all 0.3s ease;
}

.article-card:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-hover);
}

.article-thumb {
  height: 200px;
  width: 100%;
  object-fit: cover;
}

.article-body {
  padding: 24px;
}

.article-date {
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-bottom: 8px;
}

.article-title {
  font-size: 1.2rem;
  font-weight: 800;
  margin-bottom: 10px;
  line-height: 1.4;
  color: var(--text-dark);
}

.article-title:hover {
  color: var(--primary-dark);
}

.article-snippet {
  font-size: 0.9rem;
  color: var(--text-muted);
  line-height: 1.6;
  margin-bottom: 16px;
}

/* FOOTER */
.footer {
  background: #0f172a;
  color: #94a3b8;
  padding-top: 70px;
  padding-bottom: 30px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 50px;
}

.footer-brand h3 {
  color: #fff;
  font-size: 1.4rem;
  font-weight: 800;
  margin-bottom: 14px;
}

.footer-links h4 {
  color: #fff;
  font-size: 1.05rem;
  font-weight: 700;
  margin-bottom: 18px;
}

.footer-links ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer-links a:hover {
  color: var(--primary);
}

.social-icons {
  display: flex;
  gap: 12px;
  margin-top: 18px;
}

.social-icon {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: #1e293b;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #cbd5e1;
  transition: all 0.25s ease;
}

.social-icon:hover {
  background: var(--primary);
  color: #fff;
  transform: translateY(-3px);
}

.footer-bottom {
  padding-top: 24px;
  border-top: 1px solid #1e293b;
  text-align: center;
  font-size: 0.85rem;
}

/* STICKY WHATSAPP BUTTON */
.sticky-wa-btn {
  position: fixed;
  bottom: 28px;
  right: 28px;
  background: #25d366;
  color: #ffffff !important;
  padding: 12px 22px;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 700;
  font-size: 0.95rem;
  box-shadow: 0 10px 25px rgba(37, 211, 102, 0.4);
  z-index: 999;
  transition: all 0.3s ease;
}

.sticky-wa-btn:hover {
  transform: translateY(-3px) scale(1.03);
  box-shadow: 0 15px 30px rgba(37, 211, 102, 0.5);
}

/* RESPONSIVE DESIGN */
@media (max-width: 992px) {
  .hero-grid, .location-grid {
    grid-template-columns: 1fr;
  }
  .marketing-card {
    grid-template-columns: 1fr;
    text-align: center;
  }
  .marketing-photo {
    margin: 0 auto;
  }
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
    position: absolute;
    top: 78px;
    left: 0;
    right: 0;
    background: #ffffff;
    flex-direction: column;
    padding: 24px;
    border-bottom: 1px solid #e2e8f0;
    box-shadow: 0 15px 25px rgba(0,0,0,0.05);
    gap: 18px;
  }
  .nav-links.mobile-open {
    display: flex;
  }
  .hamburger-btn {
    display: block;
  }
  .hero-headline {
    font-size: 2.3rem;
  }
  .footer-grid {
    grid-template-columns: 1fr;
  }
  .property-specs-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
  }
}

body.script:
document.addEventListener('DOMContentLoaded', function() {
  // 1. Mobile Hamburger Menu Toggle
  const hamburgerBtn = document.getElementById('hamburger-toggle');
  const navMenu = document.getElementById('nav-menu');
  if (hamburgerBtn && navMenu) {
    hamburgerBtn.addEventListener('click', function() {
      navMenu.classList.toggle('mobile-open');
    });
    // Close menu when clicking link
    navMenu.querySelectorAll('a').forEach(link => {
      link.addEventListener('click', () => navMenu.classList.remove('mobile-open'));
    });
  }

  // 2. Hero Slider Auto-Play
  const slides = document.querySelectorAll('.hero-slide');
  const dots = document.querySelectorAll('.slider-dot');
  let currentSlide = 0;
  let slideInterval;

  function showSlide(index) {
    if (slides.length === 0) return;
    slides.forEach(s => s.classList.remove('active'));
    dots.forEach(d => d.classList.remove('active'));
    currentSlide = (index + slides.length) % slides.length;
    slides[currentSlide].classList.add('active');
    if (dots[currentSlide]) dots[currentSlide].classList.add('active');
  }

  function startSlider() {
    if (slides.length > 1) {
      slideInterval = setInterval(() => {
        showSlide(currentSlide + 1);
      }, 4500);
    }
  }

  dots.forEach((dot, idx) => {
    dot.addEventListener('click', () => {
      clearInterval(slideInterval);
      showSlide(idx);
      startSlider();
    });
  });
  startSlider();

  // 3. Filter Type Rumah (Semua | Subsidi | Komersil)
  const filterBtns = document.querySelectorAll('.filter-btn');
  const propertyCards = document.querySelectorAll('.property-card');
  filterBtns.forEach(btn => {
    btn.addEventListener('click', function() {
      filterBtns.forEach(b => b.classList.remove('active'));
      this.classList.add('active');
      const filterVal = this.getAttribute('data-filter');

      propertyCards.forEach(card => {
        if (filterVal === 'all' || card.getAttribute('data-category') === filterVal) {
          card.style.display = 'flex';
        } else {
          card.style.display = 'none';
        }
      });
    });
  });

  // 4. Modal Popup Detail Rumah & Galeri
  const modal = document.getElementById('property-detail-modal');
  const modalCloseBtn = document.getElementById('modal-close-btn');
  const modalTitle = document.getElementById('modal-title');
  const modalPrice = document.getElementById('modal-price');
  const modalSpecs = document.getElementById('modal-specs');
  const modalMainImg = document.getElementById('modal-main-img');
  const modalThumbsContainer = document.getElementById('modal-thumbs-container');
  const modalCtaWa = document.getElementById('modal-cta-wa');

  document.querySelectorAll('.open-modal-btn').forEach(btn => {
    btn.addEventListener('click', function() {
      const title = this.getAttribute('data-title');
      const price = this.getAttribute('data-price');
      const specs = this.getAttribute('data-specs');
      const images = (this.getAttribute('data-images') || '').split(',');

      if (modalTitle) modalTitle.textContent = title;
      if (modalPrice) modalPrice.textContent = price;
      if (modalSpecs) modalSpecs.textContent = specs;
      if (modalMainImg && images[0]) modalMainImg.src = images[0];

      if (modalThumbsContainer) {
        modalThumbsContainer.innerHTML = '';
        images.forEach((imgUrl, i) => {
          const thumb = document.createElement('img');
          thumb.src = imgUrl;
          thumb.className = 'modal-thumb' + (i === 0 ? ' active' : '');
          thumb.addEventListener('click', () => {
            modalMainImg.src = imgUrl;
            document.querySelectorAll('.modal-thumb').forEach(t => t.classList.remove('active'));
            thumb.classList.add('active');
          });
          modalThumbsContainer.appendChild(thumb);
        });
      }

      if (modalCtaWa) {
        modalCtaWa.href = 'https://wa.me/6281234567890?text=' + encodeURIComponent('Halo Marketing, saya ingin bertanya lebih lanjut tentang unit: ' + title + ' (' + price + ')');
      }

      if (modal) modal.classList.add('active');
    });
  });

  if (modalCloseBtn && modal) {
    modalCloseBtn.addEventListener('click', () => modal.classList.remove('active'));
    modal.addEventListener('click', (e) => {
      if (e.target === modal) modal.classList.remove('active');
    });
  }

  // 5. FAQ Accordion Toggle
  document.querySelectorAll('.faq-question').forEach(question => {
    question.addEventListener('click', function() {
      const parent = this.closest('.faq-item');
      const isActive = parent.classList.contains('active');
      document.querySelectorAll('.faq-item').forEach(item => item.classList.remove('active'));
      if (!isActive) {
        parent.classList.add('active');
      }
    });
  });
});
